$related=db_run('SELECT * FROM products WHERE is_active=1 AND category=? AND id<>? ORDER BY id DESC LIMIT 4',[$product['category'],$id])->get_result()->fetch_all(MYSQLI_ASSOC);$page_title=$product['name'].' · '.setting('site_name');include 'includes/header.php';
?>
